@Test public void nativeCase7()throws Throwable{modes("function keys($a){$r='';foreach($a as $k=>$v){$r.=$k.'|';}return $r;}global $v,$log;$v='a';$log='';set_error_handler(function($n,$m){global $log;$log.=$m.'|';return true;});class S{function __toString(){global $v,$log;$log.='S';$v='b';return 'a';}}$a=[new S(),&$v,'a','b'];$r=array_unique($a,SORT_NUMERIC);return keys($r).':'.$v.':'.$log;","0|1|:a:Object of class S could not be converted to float|Object of class S could not be converted to float|Object of class S could not be converted to float|");}
