@Test public void nativeCase11()throws Throwable{modes("function keys($a){$r='';foreach($a as $k=>$v){$r.=$k.'|';}return $r;}class S{function __toString(){throw new Exception('sentinel');}}$a=[new S(),'a'];try{$r=array_unique($a,SORT_STRING);return 'missing';}catch(Exception $e){return $e->getMessage().':'.count($a).':'.$a[1];}","sentinel:2:a");}
